process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const HTML=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  const r2=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  console.log('put',path,r2.status);
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/k.html', HTML);
  const b=await chromium.launch();
  const ctx=await b.newContext({viewport:{width:1320,height:1500}});
  const p=await ctx.newPage();
  const kl=[]; p.on('pageerror',e=>kl.push(String(e).slice(0,140)));
  await p.goto('file:///tmp/k.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(900);
  await p.screenshot({path:'/tmp/k_apz.png',fullPage:true});
  /* testuojam redagavima */
  const sav=p.locator('#i-savikaina');
  await sav.fill('30.00'); await sav.press('Enter'); await p.waitForTimeout(900);
  out.marza_po=await p.locator('#marza-b').innerText();
  out.zenklas=await p.locator('#marza-zn').innerText();
  await p.screenshot({path:'/tmp/k_marza.png'});
  /* aprasymai */
  await p.locator('.tabs button[data-t="apr"]').click(); await p.waitForTimeout(600);
  await p.screenshot({path:'/tmp/k_apr.png',fullPage:true});
  /* pardavimai */
  await p.locator('.tabs button[data-t="prd"]').click(); await p.waitForTimeout(600);
  await p.screenshot({path:'/tmp/k_prd.png',fullPage:true});
  /* istorija */
  await p.locator('.tabs button[data-t="ist"]').click(); await p.waitForTimeout(600);
  await p.screenshot({path:'/tmp/k_ist.png',fullPage:true});
  out.js_klaidos=kl;
  await b.close();
  for(const f of ['k_apz','k_marza','k_apr','k_prd','k_ist']){
    try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){}
  }
  await put('analize/kmaketas.json', Buffer.from(JSON.stringify(out,null,2)),'k');
}
main().catch(async e=>{ await put('analize/kmaketas.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
